`,xO=`// last-stand - B phrygian, 150 bpm. mood: tense, dark.
// Back to the wall. A heartbeat sub pulse that never stops, strings that tremble
// faster as intensity climbs, a filter that opens with every level.
// Fifteen sections of eight cycles (3m12s before it repeats): the held chords
// take four dark roads and the rising line climbs a new stair each time.
setcpm(150 / 4)

let A = "<Bm Cadd9 Bm Gadd9 Bm Cadd9 Am7 Bm>"
let B = "<Em Bm Cadd9 Bm Gadd9 Am7 Cadd9 Bm>"
let C = "<Bm D Gadd9 Cadd9 Bm Em Am7 Bm>"
let D = "<Cadd9 Bm Am7 Gadd9 Em Bm Cadd9 Bm>"
let P = arrange([8, A], [8, B], [8, A], [8, C], [8, D], [8, B], [8, A], [8, C], [8, D], [8, A], [8, B], [8, C], [8, D], [8, B], [8, A])

// the rising line: eight cycles
let stair = "<[0 ~ 1 ~ 0 ~ 2 ~] [4 ~ 3 ~ 2 ~ 1 ~] [0 ~ 2 ~ 4 ~ 2 ~] [3 ~ 2 ~ 1 ~ 0 ~] [0 ~ 1 ~ 3 ~ 1 ~] [5 ~ 4 ~ 2 ~ 1 ~] [2 ~ 1 ~ 0 ~ 1 ~] [4 ~ 5 ~ 4 ~ 2 ~]>"
let line = arrange([8, stair], [8, stair.add(1)], [8, stair.rev()], [8, stair.add(3)], [8, stair.add(-1)],
  [8, stair.rev().add(2)], [8, stair], [8, stair.add(2).rev()], [8, stair.add(4)], [8, stair.rev()],
  [8, stair.add(1)], [8, stair.add(-1).rev()], [8, stair.add(3)], [8, stair.rev().add(1)], [8, stair])

stack(
  // 0: the heartbeat and a dark held chord
  note("b1 ~ ~ ~ b1 ~ [b1 ~] ~").s("sine").decay(.25).sustain(0).gain(.5).lpf(150),
  chord(P).voicing().mode("below:d4")
    .s("sawtooth").attack(.8).clip(.9).release(.12).gain(.22)
    .lpf(ref(() => 400 + INTENSITY * 900)).room(.7).roomsize(6).orbit(2),
  // 1: tremolo strings (sixteenth gates), taiko on the heart
  layer(1, stack(
    n("0 2 4").chord(P).voicing().mode("above:b3").struct("x*16")
      .s("supersaw").unison(2).detune(.2).decay(.1).sustain(.6).release(.05).gain(.3)
      .lpf(ref(() => 600 + INTENSITY * 800)).roomsize(6).orbit(2),
    s("taiko:1 ~ ~ ~ taiko:1 ~ ~ ~").gain(.6).room(.3))),
  // 2: war drums and the rising line
  layer(2, stack(
    s("taiko:0 taiko:1 ~ taiko:0 taiko:1 ~ taiko:0 taiko:1").gain(.7).room(.3),
    n(line).scale("b3:phrygian")
      .s("sawtooth").attack(.02).release(.3).gain(.45).lpf(1000).lpenv(2).lpd(.25).room(.4).roomsize(6).orbit(2))),
  // 3: choir, cymbal swell, everything open
  layer(3, stack(
    chord(P).voicing().mode("below:f#5").s("sawtooth").lpq(4).attack(.3).clip(.9).release(.12).gain(.2).lpf(2600).room(.7).roomsize(6).orbit(2),
    s("swell:0 ~ ~ ~ ~ ~ ~ ~").slow(2).gain(.3),
    s("snare:1*8").gain(.18)))
).postgain(.29)
`,SO=`// northern-pass - G mixolydian, 96 bpm. mood: adventurous, epic.
// Setting out over snowy mountains: a horn call, a striding bass, a frame drum
// and a tin whistle. Level 1 adds the lute, level 2 the full march.
// Ten sections of eight cycles (3m20s before it repeats): four chord journeys,
// and the horn call climbs, turns and answers itself section by section.
setcpm(96 / 4)

let A = "<G F C G G F Dm F>"
let B = "<C G F C Em F G Dm>"
let C = "<Am F C G Am Em F G>"
let D = "<Dm C F G Dm Am F G>"
let P = arrange([8, A], [8, B], [8, A], [8, C], [8, D], [8, B], [8, A], [8, C], [8, D], [8, A])

// the horn call: eight cycles, a rest of a bar after each call
let call = "<[0@3 4@2 ~ 2 ~] ~ [2@3 1@2 ~ 0@2] ~ [4@3 5@2 ~ 7 ~] ~ [5@3 4@2 ~ 2 ~] [2@2 1@2 0@4]>"
let horn = arrange([8, call], [8, call.add(2)], [8, call.rev()], [8, call.add(-2)], [8, call.add(4)],
  [8, call.rev().add(2)], [8, call], [8, call.add(-2).rev()], [8, call.add(2)], [8, call.rev().add(-2)])

stack(
  // 0: open fifths in the strings, the striding bass, the horn call
  chord(P).voicing().mode("below:d4")
    .s("supersaw").unison(2).detune(.2).attack(.6).clip(.9).release(.2).gain(.17)
    .lpf(1500).room(.6).roomsize(6).orbit(2),
  note(P.rootNotes(2)).s("triangle").attack(.02).decay(.25).sustain(.4).release(.2).gain(.5)
    .struct("x ~ x ~ x x x x"),
  n(horn).scale("g3:mixolydian")
    .s("sawtooth").attack(.08).release(.3).gain(.4)
    .lpf(500).lpenv(3).lpa(.12).lpd(.6).room(.7).roomsize(6).orbit(2),
  s("frame:1 ~ ~ ~ frame:1 ~ ~ ~").gain(.45).room(.3),
  // 1: the lute joins, the whistle answers the horn
  layer(1, stack(
    n("~ 0 ~ 2 ~ 0 ~ 2").chord(P).voicing().mode("above:g3")
      .s("strum").gain(.55).room(.4),
    n("~ ~ ~ ~ 4 [5 4] 2 ~ ~ ~ ~ ~ 2 [3 2] 0 ~".slow(2).add("<0 0 -1 0 -2 0 -3 0>"))
      .scale("g4:mixolydian")
      .s("whistle").gain(.45).attack(.03).release(.15).lpf(2800).room(.5).roomsize(6).orbit(2))),
  // 2: the march
  layer(2, stack(
    s("timp:0 ~ ~ timp:0 ~ ~ timp:0 ~").gain(.55).room(.3),
    s("~ ~ frame:0 ~ ~ ~ frame:0 ~").gain(.4),
    n("<0 0 0 0 0 0 0 0>*2".add("<0 0 -1 0 0 0 -2 0>")).scale("g3:mixolydian")
      .s("sawtooth").attack(.05).release(.15).gain(.18).lpf(1000).lpenv(2).lpd(.3).roomsize(6).orbit(2)))
).postgain(.45)
`,CO=`// victors-hymn - Bb major, 108 bpm. mood: triumphant, epic.
// Banners up. A brass chorale over choir and bells: noble, not cheesy. Level 0
// is the hymn, level 1 adds the timpani roll and the cymbal.
// Eleven sections of eight cycles (3m16s before it repeats): four chord
// journeys, and the brass sings a new verse of the hymn over each.
setcpm(108 / 4)

let A = "<Bb F Gm7 Eb^7 Bb F Eb F>"
let B = "<Gm7 Eb^7 Bb F Cm7 Gm7 F Bb>"
let C = "<Eb^7 Bb F Gm7 Eb^7 Cm7 F Bb>"
let D = "<Bb Dm7 Eb^7 F Gm7 Cm7 F Bb>"
